local SickleSmith = {}
local PRODUCTS = {
    simple_iron_sickle = { name = "Preprost železen srp", ironCost = 2, woodCost = 1, time = 3, cost = 50, food = 10, happiness = 1, description = "Preprost železen srp za žetev." },
    steel_blade_sickle = { name = "Jeklenorezni srp", ironCost = 2, steelCost = 1, woodCost = 1, time = 5, cost = 140, food = 18, happiness = 1, prestige = 2, description = "Jeklenorezni srp za trgovce." },
    silver_trimmed_sickle = { name = "Srebrnoobrobljeni srp", ironCost = 2, silverCost = 1, steelCost = 1, woodCost = 1, time = 8, cost = 340, food = 28, happiness = 2, prestige = 6, description = "Srebrnoobrobljeni srp za plemiče." },
    gold_trimmed_sickle = { name = "Zlatookrasni srp", ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, woodCost = 1, time = 12, cost = 800, food = 40, happiness = 3, prestige = 14, description = "Zlatookrasni srp za visoke plemiče." },
    jewel_set_sickle = { name = "Draguljasta srp", ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, woodCost = 1, jewelCost = 1, time = 16, cost = 1800, food = 55, happiness = 5, prestige = 27, description = "Srp z draguljem za visoko plemstvo." },
    royal_grand_sickle = { name = "Kraljevski veliki srp", ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 4000, food = 75, happiness = 12, prestige = 58, description = "Veliki kraljevski srp z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sickle_workshop = { name = "Srparska delavnica", cost = { gold = 240, wood = 120, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 880, wood = 280, stone = 240, silver = 6, steel = 4 }, upkeep = 20, qualityBonus = 18 },
    master_sickle_atelier = { name = "Mojstrski srparski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
SickleSmith.ironStock = 14; SickleSmith.steelStock = 10; SickleSmith.woodStock = 10; SickleSmith.silverStock = 6; SickleSmith.goldStock = 6; SickleSmith.jewelStock = 4; SickleSmith.pearlStock = 4
SickleSmith.productStock = {}; SickleSmith.buildings = {}; SickleSmith.maker = nil; SickleSmith.activeMaking = {}; SickleSmith.totalProducts = 0; SickleSmith.dayTimer = 0
function SickleSmith.init() SickleSmith.ironStock=14; SickleSmith.steelStock=10; SickleSmith.woodStock=10; SickleSmith.silverStock=6; SickleSmith.goldStock=6; SickleSmith.jewelStock=4; SickleSmith.pearlStock=4; SickleSmith.productStock={}; SickleSmith.buildings={}; SickleSmith.maker=nil; SickleSmith.activeMaking={}; SickleSmith.totalProducts=0; SickleSmith.dayTimer=0; print("[SickleSmith] Royal Sickle Smith System initialized (6 products, 4 buildings)") end
function SickleSmith.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SickleSmith.maker={name=n or ("Srpak "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Srpak najet: %s (spretnost: %d)",SickleSmith.maker.name,s),"success") end; return true end
function SickleSmith.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SickleSmith.build(id) local ok,e=SickleSmith.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SickleSmith.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SickleSmith.getQualityBonus() local b=0; for _,bd in ipairs(SickleSmith.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SickleSmith.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SickleSmith.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and SickleSmith.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and SickleSmith.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and SickleSmith.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SickleSmith.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SickleSmith.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SickleSmith.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SickleSmith.buildings==0 then return false,"Potrebna srparska delavnica" end; if not SickleSmith.maker then return false,"Potreben srpak" end; return true end
function SickleSmith.make(pt,qty) qty=qty or 1; local ok,e=SickleSmith.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SickleSmith.ironStock=SickleSmith.ironStock-d.ironCost*qty end; if d.steelCost then SickleSmith.steelStock=SickleSmith.steelStock-d.steelCost*qty end; if d.woodCost then SickleSmith.woodStock=SickleSmith.woodStock-d.woodCost*qty end; if d.silverCost then SickleSmith.silverStock=SickleSmith.silverStock-d.silverCost*qty end; if d.goldCost then SickleSmith.goldStock=SickleSmith.goldStock-d.goldCost*qty end; if d.jewelCost then SickleSmith.jewelStock=SickleSmith.jewelStock-d.jewelCost*qty end; if d.pearlCost then SickleSmith.pearlStock=SickleSmith.pearlStock-d.pearlCost*qty end; local t=d.time; if SickleSmith.maker then t=math.max(1,t-math.floor(SickleSmith.maker.skill/14)) end; table.insert(SickleSmith.activeMaking,{id="sickle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SickleSmith.completeMaking(m) local q=1.0+(SickleSmith.getQualityBonus()/100); if SickleSmith.maker then q=q+(SickleSmith.maker.skill/140) end; q=math.min(2.5,q); SickleSmith.productStock[m.productType]=(SickleSmith.productStock[m.productType] or 0)+m.quantity; SickleSmith.totalProducts=SickleSmith.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SickleSmith.maker then SickleSmith.maker.itemsMade=SickleSmith.maker.itemsMade+m.quantity; if math.random()<0.25 then SickleSmith.maker.skill=math.min(100,SickleSmith.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Srp izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sickle.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function SickleSmith.update(dt) if not _G.state then return end; SickleSmith.dayTimer=SickleSmith.dayTimer+dt; if SickleSmith.dayTimer>=30 then SickleSmith.dayTimer=0; for i=#SickleSmith.activeMaking,1,-1 do local m=SickleSmith.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SickleSmith.completeMaking(m); table.remove(SickleSmith.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SickleSmith.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SickleSmith.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SickleSmith.getStats() return {ironStock=SickleSmith.ironStock,steelStock=SickleSmith.steelStock,woodStock=SickleSmith.woodStock,silverStock=SickleSmith.silverStock,goldStock=SickleSmith.goldStock,jewelStock=SickleSmith.jewelStock,pearlStock=SickleSmith.pearlStock,productStock=SickleSmith.productStock,numBuildings=#SickleSmith.buildings,hasMaker=SickleSmith.maker~=nil,makerName=SickleSmith.maker and SickleSmith.maker.name or "—",makerSkill=SickleSmith.maker and SickleSmith.maker.skill or 0,activeMaking=#SickleSmith.activeMaking,totalProducts=SickleSmith.totalProducts} end
return SickleSmith
